// Разбирает ответ ИИ: одна запись на каждый найденный заказ
// Ответ может прийти строкой JSON или уже разобранным объектом
const getData = (j) => {
  const pick = (t) => (typeof t === 'string' ? JSON.parse(t) : t);
  if (j.text !== undefined) return pick(j.text);
  if (Array.isArray(j.output)) {
    for (const o of j.output) {
      for (const c of (o.content || [])) {
        if (c.text !== undefined) return pick(c.text);
      }
    }
  }
  if (j.message && j.message.content !== undefined) return pick(j.message.content);
  return null;
};

const out = [];
$input.all().forEach((item) => {
  let data;
  try {
    data = getData(item.json);
  } catch (e) {
    return;
  }
  if (!data || data.email_type === 'other' || !Array.isArray(data.jobs)) return;
  for (const job of data.jobs) {
    const title = String(job.title || '').trim();
    if (!title) continue;
    const url = String(job.url || '').trim();
    const idMatch = url.match(/~0?[0-9a-z]{10,}/i);
    const job_key = idMatch ? idMatch[0].toLowerCase() : title.toLowerCase().replace(/\s+/g, ' ').slice(0, 200);
    out.push({
      json: {
        job_key,
        kind: data.email_type === 'invite' ? 'invite' : 'job',
        title: title.slice(0, 300),
        title_ru: String(job.title_ru || title).slice(0, 300),
        url: idMatch ? 'https://www.upwork.com/jobs/' + idMatch[0] : url,
        description: String(job.description || '').replace(/https?:\/\/\S+/g, '').slice(0, 3000),
        description_ru: String(job.description_ru || '').slice(0, 2500),
        budget: String(job.budget || ''),
        client: String(job.client || ''),
        skills: String(job.skills || ''),
        score: Math.max(0, Math.min(10, Math.round(Number(job.score) || 0))),
        summary_ru: String(job.summary_ru || ''),
        why_ru: String(job.why_ru || ''),
        risks_ru: String(job.risks_ru || ''),
      },
    });
  }
});
return out;

// Карточка заказа для Telegram (HTML), всё по-русски
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const j = $json;
const head = (j.kind === 'invite' ? '📩 <b>ПРИГЛАШЕНИЕ от клиента</b>' : '🆕 <b>Новый заказ</b>') + '  ' + '⭐'.repeat(Math.max(1, Math.round(j.score / 2))) + ' ' + j.score + '/10';
const parts = [
  head,
  '<b>' + esc(j.title_ru) + '</b>\n<i>' + esc(j.title) + '</i>',
  [j.budget ? '💰 ' + esc(j.budget) : '', j.client ? '👤 ' + esc(j.client) : ''].filter(Boolean).join('\n'),
  '📝 <b>Суть:</b> ' + esc(j.summary_ru),
  j.description_ru ? '📄 <b>Описание (перевод):</b>\n' + esc(String(j.description_ru).slice(0, 1500)) : '',
  '✅ ' + esc(j.why_ru) + (j.risks_ru ? '\n⚠️ ' + esc(j.risks_ru) : ''),
];
return { json: { ...j, card: parts.filter(Boolean).join('\n\n').slice(0, 4000), open_url: /^https?:\/\//.test(j.url) ? j.url : 'https://www.upwork.com/nx/find-work/' } };

// Сообщения и офферы клиентов из писем Upwork
const getData = (j) => {
  const pick = (t) => (typeof t === 'string' ? JSON.parse(t) : t);
  if (j.text !== undefined) return pick(j.text);
  for (const o of (j.output || [])) for (const c of (o.content || [])) if (c.text !== undefined) return pick(c.text);
  return null;
};

const out = [];
$input.all().forEach((item, i) => {
  let d;
  try { d = getData(item.json); } catch (e) { return; }
  if (!d || !['message', 'offer'].includes(d.email_type) || !d.message) return;
  const m = d.message;
  const email = $('MY PROFILE').itemMatching(i).json;
  out.push({
    json: {
      email_id: String(email.id || email.subject || Date.now()),
      kind: d.email_type,
      client: String(m.client || ''),
      job_title: String(m.job_title || ''),
      text: String(m.text || '').replace(/https?:\/\/\S+/g, '').slice(0, 4000),
      text_ru: String(m.text_ru || ''),
      meaning_ru: String(m.meaning_ru || ''),
      reply_en: String(m.reply_en || ''),
      reply_ru: String(m.reply_ru || ''),
      is_partial: !!m.is_partial,
    },
  });
});
return out;

// Карточка сообщения клиента для Telegram (HTML)
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const j = $json;
const head = j.kind === 'offer' ? '🎉 <b>Оффер / контракт</b>' : '💬 <b>Клиент написал</b>';
const parts = [
  head + (j.client ? ' — ' + esc(j.client) : '') + (j.job_title ? '\n<i>' + esc(j.job_title) + '</i>' : ''),
  '🇷🇺 <b>Перевод:</b>\n' + esc(j.text_ru),
  j.meaning_ru ? '💡 <b>Что хочет:</b> ' + esc(j.meaning_ru) : '',
  j.is_partial ? '⚠️ В письме только часть сообщения. Полный текст — в чате Upwork (можно скопировать и переслать мне для перевода).' : '',
  j.reply_en ? '✍️ <b>Предлагаю ответить</b> (нажмите, чтобы скопировать):\n<pre>' + esc(j.reply_en) + '</pre>\n🔁 ' + esc(j.reply_ru) : '',
];
return { json: { ...j, card: parts.filter(Boolean).join('\n\n').slice(0, 4000) } };

