SELECT
  coalesce((SELECT string_agg(t, E'\n') FROM (SELECT '- ' || title || ' | ' || coalesce(budget, '') || ' | ' || coalesce(skills, '') AS t FROM upwork_jobs WHERE status = 'taken' ORDER BY created_at DESC LIMIT 15) a), '(пока нет)') AS taken,
  coalesce((SELECT string_agg(t, E'\n') FROM (SELECT '- ' || title || ' | ' || coalesce(budget, '') || ' | ' || coalesce(skills, '') AS t FROM upwork_jobs WHERE status = 'skipped' ORDER BY created_at DESC LIMIT 25) b), '(пока нет)') AS skipped;
